#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(std::string(#x)+": "+cudaGetErrorString(e));}while(0)
using V=std::vector<double>;
template<class T>struct Buffer{T*base,*d;size_t n,total;Buffer(size_t n):n(n),total(n+64){CK(cudaMalloc(&base,total*sizeof(T)));d=base+32;CK(cudaMemset(base,165,total*sizeof(T)));}~Buffer(){cudaFree(base);}void zero(){CK(cudaMemset(d,0,n*sizeof(T)));}void put(const std::vector<T>&x){if(x.size()!=n)throw std::runtime_error("input bounds");CK(cudaMemcpy(d,x.data(),n*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>read(){std::vector<T>x(n);CK(cudaMemcpy(x.data(),d,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}std::vector<uint8_t>raw(){std::vector<uint8_t>x(total*sizeof(T));CK(cudaMemcpy(x.data(),base,x.size(),cudaMemcpyDeviceToHost));return x;}};
template<class T>struct Pitched{T*base,*d;size_t n,blocks,pitch,stride,total;Pitched(size_t n,size_t blocks):n(n),blocks(blocks){CK(cudaMallocPitch(&base,&pitch,n*sizeof(T),blocks+2));stride=pitch/sizeof(T);total=stride*(blocks+2);d=base+stride;if(pitch!=((n*sizeof(T)+511)/512)*512)throw std::runtime_error("actual source pitch differs from declared512byte alignment");CK(cudaMemset(base,165,total*sizeof(T)));}~Pitched(){cudaFree(base);}void reset(){CK(cudaMemset(base,165,total*sizeof(T)));}std::vector<T>read(){std::vector<T>x(stride*blocks);CK(cudaMemcpy(x.data(),d,x.size()*sizeof(T),cudaMemcpyDeviceToHost));return x;}std::vector<uint8_t>raw(){std::vector<uint8_t>x(total*sizeof(T));CK(cudaMemcpy(x.data(),base,x.size(),cudaMemcpyDeviceToHost));return x;}};
struct State{int ci;HCase c;int blocks,threads;Buffer<int>R,C,F,next,jia,diam,source;Buffer<float>bc;Pitched<int>d,Q,Q2,S,ep;Pitched<uint64_t>sigma;Pitched<float>delta;State(int ci,const HCase&c):ci(ci),c(c),blocks(80),threads(1024),R(c.n+1),C(2*c.m),F(2*c.m),next(1),jia(1),diam(512),source(0),bc(c.n),d(c.n,80),Q(c.n,80),Q2(c.n,80),S(c.n,80),ep(c.n+1,80),sigma(c.n,80),delta(c.n,80){cudaDeviceProp p;CK(cudaGetDeviceProperties(&p,0));if(p.multiProcessorCount!=80||p.maxThreadsPerBlock!=1024)throw std::runtime_error("source V100 grid expectation differs");R.put(c.R);C.put(c.C);F.put(c.F);}void reset(){bc.zero();next.put(std::vector<int>{80});jia.zero();diam.zero();d.reset();Q.reset();Q2.reset();S.reset();ep.reset();sigma.reset();delta.reset();CK(cudaDeviceSynchronize());}V prefix(){V a;auto append=[&](auto&b){auto x=b.read();a.insert(a.end(),x.begin(),x.end());};append(R);append(C);append(F);append(bc);append(next);append(jia);append(diam);return a;}double run(){CK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();bc_kernel<<<blocks,threads>>>(bc.d,R.d,C.d,F.d,c.n,c.m,d.d,reinterpret_cast<const unsigned long long*>(sigma.d),delta.d,Q.d,Q2.d,S.d,ep.d,next.d,d.pitch,sigma.pitch,delta.pitch,Q.pitch,Q2.pitch,S.pitch,ep.pitch,0,c.n,jia.d,diam.d,source.d,false);CK(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();}};
struct Audit{std::vector<uint8_t>bytes,guards;std::string layout="{\"buffers\":[";bool first=true;void add(const char*name,const char*dtype,size_t count,size_t width,size_t logical,size_t blocks,size_t stride,const std::vector<uint8_t>&raw,bool pitched){if(!first)layout+=",";first=false;size_t offset=bytes.size(),guardoff=guards.size();bytes.insert(bytes.end(),raw.begin(),raw.end());std::vector<std::pair<size_t,size_t>>segments;if(pitched){segments.emplace_back(0,stride*width);for(size_t row=1;row<=blocks;row++)segments.emplace_back((row*stride+logical)*width,(stride-logical)*width);segments.emplace_back((blocks+1)*stride*width,stride*width);}else{segments.emplace_back(0,32*width);segments.emplace_back((32+logical)*width,32*width);}for(auto[a,n]:segments)guards.insert(guards.end(),raw.begin()+a,raw.begin()+a+n);layout+="{\"name\":\""+std::string(name)+"\",\"dtype\":\""+dtype+"\",\"offset_bytes\":"+std::to_string(offset)+",\"count_elements\":"+std::to_string(count)+",\"element_bytes\":"+std::to_string(width)+",\"logical_width_elements\":"+std::to_string(logical)+",\"rows\":"+std::to_string(blocks)+",\"stride_elements\":"+std::to_string(stride)+",\"pitched\":"+(pitched?"true":"false")+",\"guard_offset_bytes\":"+std::to_string(guardoff)+",\"guard_count_bytes\":"+std::to_string(guards.size()-guardoff)+",\"guard_segments\":[";bool sf=true;for(auto[a,n]:segments){if(!sf)layout+=",";sf=false;layout+="["+std::to_string(a)+","+std::to_string(n)+"]";}layout+="]}";}bool save(const std::string&path){layout+="]}";std::ofstream f(path+".raw.bin",std::ios::binary);f.write((char*)bytes.data(),bytes.size());std::ofstream g(path+".guards.u8",std::ios::binary);g.write((char*)guards.data(),guards.size());std::ofstream j(path+".layout.json");j<<layout;return std::all_of(guards.begin(),guards.end(),[](uint8_t x){return x==165;});}};
bool capture(State&s,const std::string&path,V&output,double&ma,double&mr){auto bc=s.bc.read();bool ok=check_bc(s.ci,bc.data(),ma,mr);auto d=s.d.read(),Q=s.Q.read(),Q2=s.Q2.read(),S=s.S.read(),ep=s.ep.read();auto sigma=s.sigma.read();auto delta=s.delta.read();auto diam=s.diam.read();int next=s.next.read()[0],jia=s.jia.read()[0];ok=check_rows(s.ci,s.blocks,d.data(),s.d.stride,sigma.data(),s.sigma.stride,delta.data(),s.delta.stride,Q.data(),s.Q.stride,Q2.data(),s.Q2.stride,S.data(),s.S.stride,ep.data(),s.ep.stride,diam.data(),next,jia)&&ok;for(float v:bc)output.push_back(double(v*.5f));output.push_back(next);/* Actualadaptiveflag/diameters retainedraw, not artificially forced into referenceidentity. */Audit a;
#define LINEAR(name,dtype) a.add(#name,dtype,s.name.total,sizeof(*s.name.d),s.name.n,1,0,s.name.raw(),false)
#define PITCH(name,dtype) a.add(#name,dtype,s.name.total,sizeof(*s.name.d),s.name.n,s.name.blocks,s.name.stride,s.name.raw(),true)
LINEAR(R,"int32");LINEAR(C,"int32");LINEAR(F,"int32");LINEAR(next,"int32");LINEAR(jia,"int32");LINEAR(diam,"int32");LINEAR(source,"int32");LINEAR(bc,"float32");PITCH(d,"int32");PITCH(Q,"int32");PITCH(Q2,"int32");PITCH(S,"int32");PITCH(ep,"int32");PITCH(sigma,"uint64");PITCH(delta,"float32");bool guards=a.save(path);output.push_back(guards?0:1);fprintf(stderr,"case%d n%d next%d jia%d independent%s guards%s\n",s.ci,s.c.n,next,jia,ok?"PASS":"FAIL",guards?"PASS":"FAIL");return ok&&guards;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("persistent raw evidence folder required");std::filesystem::create_directories(argv[1]);auto cs=hload();std::vector<std::unique_ptr<State>>states;for(int ci=0;ci<int(cs.size());ci++)states.emplace_back(std::make_unique<State>(ci,cs[ci]));for(auto&s:states){s->reset();s->run();}for(int trial=1;trial<=5;trial++){V pre,out;double seconds=0,ma=0,mr=0;bool ok=true;for(auto&s:states){s->reset();auto p=s->prefix();pre.insert(pre.end(),p.begin(),p.end());seconds+=s->run();std::string path=std::string(argv[1])+"/native_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_case"+std::to_string(s->ci);ok=capture(*s,path,out,ma,mr)&&ok;}pre.insert(pre.end(),out.begin(),out.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)pre.data(),pre.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum4_full_exact_Brandes_source_kernel_and_context_completion\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",pre.size(),ma,mr,path.c_str(),pre.size());if(!ok)return 1;}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
